from collections import deque
# Connected 8-background component containing cells adjacent to marker; try 8-connectivity
seen=set(); q=deque()
for dr in range(-1,2):
 for dc in range(-1,2):
  rr,cc=0+dr,11+dc
  if 0<=rr<12 and 0<=cc<12 and g[rr][cc]==8:
   seen.add((rr,cc)); q.append((rr,cc))
while q:
 r,c=q.popleft()
 for dr in range(-1,2):
  for dc in range(-1,2):
   rr,cc=r+dr,c+dc
   if 0<=rr<12 and 0<=cc<12 and g[rr][cc]==8 and (rr,cc) not in seen:
    seen.add((rr,cc));q.append((rr,cc))
out=[row[:] for row in g]
for r,c in seen:
 if r in (0,11) or c in (0,11) or any(0<=r+dr<12 and 0<=c+dc<12 and g[r+dr][c+dc]==1 for dr in range(-1,2) for dc in range(-1,2)):
  out[r][c]=7
